package ccxt

// IOrderBook is a lightweight wrapper around *OrderBook to satisfy
// the signatures generated by the transpiler wrapper (WatchOrderBook etc).
// At the time of writing it does not add extra behaviour beyond what
// OrderBook already provides, however having a distinct type keeps the
// door open for future extensions (e.g. typed interfaces, additional
// statistics, etc.).

type IOrderBook struct {
	*WsOrderBook
}

// NewIOrderBook attempts to convert arbitrary return values coming from the
// core WatchOrderBook / FetchOrderBook methods into an IOrderBook instance.
// The input is expected to be either an *OrderBook already, or a snapshot
// map[string]any coming from REST/WS which will be used to seed a
// fresh order-book.
func NewIOrderBook(v any) IOrderBook {
	switch t := v.(type) {
	case *WsOrderBook:
		return IOrderBook{t}
	case map[string]any:
		ob := (&Exchange{}).OrderBook(t) // depth defaults to max-int
		return IOrderBook{ob}
	default:
		// unknown type – create empty orderbook
		ob := NewWsOrderBook(map[string]any{}, nil)
		return IOrderBook{ob}
	}
}

// truncateBidAskRows keeps only price and amount in every level so that
// 3-wide counted and indexed rows survive parseOrderBookEntries, see
// https://github.com/ccxt/ccxt/issues/29586
func truncateBidAskRows(side any) any {
	rows, ok := side.([][]any)
	if !ok {
		return side
	}
	out := make([][]any, len(rows))
	for i, row := range rows {
		if len(row) > 2 {
			out[i] = row[:2]
		} else {
			out[i] = row
		}
	}
	return out
}

func NewOrderBookFromWs(v any) OrderBook {
	switch t := v.(type) {
	case OrderBookInterface:
		// covers *WsOrderBook and all embedding types (*CountedOrderBook, *IndexedOrderBook);
		// a concrete *WsOrderBook case never matches embedding types and silently produced
		// empty books with timestamp 0, see https://github.com/ccxt/ccxt/issues/29586
		ob := t.ToMap()
		// counted and indexed sides carry 3-wide rows of price and size and count or id
		// which parseOrderBookEntries drops, normalize every row to price and amount
		ob["asks"] = truncateBidAskRows(ob["asks"])
		ob["bids"] = truncateBidAskRows(ob["bids"])
		return NewOrderBook(ob)
	case map[string]any:
		return NewOrderBook(t)
	default:
		// unknown type – create empty orderbook
		ob := NewWsOrderBook(map[string]any{}, nil)
		return NewOrderBook(ob.ToMap())
	}
}
